import type { Seed } from './roadmap-build';

// "System design at scale" learning path — 120 questions (15 levels × 8),
// easiest → hardest: scaling, load balancing, caching, replication, sharding,
// queues, consistency/CAP, rate limiting, CDNs, failure modes, observability,
// trade-offs and estimation. Built directly (ids rm-sysdesign-1 … 120).
export const systemDesignSeeds: Seed[] = [
  // Level 1 — System Design Basics
  { q: 'A team is deciding how an API, cache, database, and queue should work together under expected traffic and failures. What kind of work is this?', opts: ['Detailed UI design for one client screen', 'Arranging components to meet load and failure requirements', 'Unit design inside a single pure function', 'Source-control design for the repository branches'], a: 1, e: 'System design fixes the components, the data flow between them, and the trade-offs, so the whole service meets requirements such as scale, reliability, latency, and cost. The other options are design work at a much smaller scope - one screen, one function, one repository - and none of them decides how the API, cache, database, and queue behave together.', tags: ['System Design', 'basics'], intro: 'Notice the scope of the decision: it spans several components and how they behave together under load.' },
  { q: '“Users can upload photos” is a feature requirement. Which option is a non-functional requirement for the same service?', opts: ['Users can add a caption to each photo', 'Ninety-five percent of uploads complete within two seconds', 'Users can delete a photo they own', 'Moderators can remove a reported photo'], a: 1, e: 'Non-functional requirements state how well the service must operate - latency, capacity, availability, durability, cost - and can be measured against a target such as 95% within two seconds. Adding a caption, deleting your own photo, and moderator removal are all features: they say what the system does, not the quality bar it has to hold while doing it.', intro: 'All four are requirements; sort them by whether each names something the service does or a bar it has to hold while doing it.', tags: ['System Design', 'requirements'] },
  { q: 'A monitoring chart shows that the p95 time from receiving an API request to sending its response is 180 ms. What is it measuring?', opts: ['Throughput over the monitoring interval', 'Request latency at the 95th percentile', 'Total storage consumed by the service', 'Concurrent server capacity before saturation'], a: 1, e: 'Latency is the elapsed time of a single operation, and p95 means 95% of the measured requests finished at or below 180 ms while the slowest 5% took longer. Throughput would be a rate - requests per second - not a duration, so a service can hold a low p95 and still be limited in how many requests it handles.', intro: 'The chart\'s unit is milliseconds for one request; then ask what the percentile adds to that number.', tags: ['System Design', 'latency'] },
  { q: 'A queue consumer handles 4,000 messages per second while each message takes 20 ms end to end. Which number describes throughput?', opts: ['20 ms per message', '4,000 messages per second', 'The queue’s total retained bytes', 'The number of consumer instances'], a: 1, e: 'Throughput is completed work per unit time. Latency measures how long one item takes; the two metrics answer different questions.', intro: 'Both figures describe the same consumer; decide which question each of the two numbers answers.', tags: ['System Design', 'throughput'] },
  { q: 'A service-level objective says the API must be usable for 99.95% of each month. Which quality does that percentage describe?', opts: ['Consistency of replicated records', 'Availability over the measurement period', 'Throughput per provisioned server', 'Durability of accepted writes'], a: 1, e: 'Availability is the share of the period during which the service is usable, so 99.95% of a 30-day month leaves about 21.6 minutes of downtime as the error budget. Durability is about not losing writes the service already accepted, and consistency is about which value a read returns; neither is measured as uptime across a month.', intro: 'Turn the percentage into a budget: how much of the month may the API be unusable?', tags: ['System Design', 'availability'] },
  { q: 'Before choosing a database for a new chat service, what should the team establish first?', opts: ['The cloud vendor\'s default database offering', 'Expected traffic, data size, and reliability targets', 'The final table and index names', 'The visual layout of the mobile conversation screen'], a: 1, e: 'Traffic volume, data size, and reliability targets are what make one database a better fit than another, so they have to exist before the choice does. Starting from the vendor default, the table names, or the screen layout commits the design before anyone knows the load it must carry, and reversing a storage choice later is expensive.', intro: 'Ask what information would make one database a better fit than another, and whether the team has it yet.', tags: ['System Design', 'process'] },
  { q: 'Traffic grows tenfold, and the service can meet it by adding instances without redesigning every component. Which property does this show?', opts: ['Durability, because every request reaches permanent storage', 'Scalability, because capacity can grow with added resources', 'Consistency, because every instance returns identical data immediately', 'Idempotency, because requests may be retried safely'], a: 1, e: 'Scalability is the ability to absorb higher load by adding resources while service quality stays acceptable. Durability, consistency, and idempotency are real properties too, but none of them describes capacity that grows with the resources you add; a durable system can still fall over at ten times the traffic.', intro: 'Focus on what changed to meet the load: resources were added, not code rewritten.', tags: ['System Design', 'scalability'] },
  { q: 'Every application instance depends on one configuration service, and no request can start when that service is down. What role does it have?', opts: ['A redundant failover component', 'A single point of failure for request handling', 'A read-through cache for application data', 'A rate limiter that protects downstream capacity'], a: 1, e: 'A single point of failure has no effective redundancy and can take down the larger system. Replication, fallback behavior, or removing the synchronous dependency can reduce the risk.', intro: 'Ask what happens to every other component the moment this one stops answering.', tags: ['System Design', 'reliability'] },

  // Level 2 — Client–Server & APIs
  { q: 'A web app and a mobile app both use the same ordering rules. Where should the shared business rules run?', opts: ['Independently in each client, with the database exposed to both', 'On a server that exposes the same API to both clients', 'Only in database triggers, with clients writing tables directly', 'In the web client, with the mobile app copying its responses'], a: 1, e: 'Putting shared rules behind a server API gives both clients one trusted implementation and keeps the database private. Client-side checks can improve UX, but the server must enforce the rules.', intro: 'Two clients must reach the same verdict; ask where a rule can be enforced rather than merely repeated.', tags: ['System Design', 'client-server'] },
  { q: 'Which endpoint design uses HTTP resource semantics most consistently?', opts: ['POST /getOrder with { action: "read" } for every operation', 'GET /orders/42 to read and DELETE /orders/42 to remove the same resource', 'GET /orders/42/delete to remove an order', 'POST /rpc with a method name for every operation'], a: 1, e: 'A REST-style API models an order as a resource and uses HTTP methods for the operation. RPC can also be valid, but it is a different API style.', intro: 'Look at where the action is expressed: in the HTTP method, or inside the path and body?', tags: ['System Design', 'rest'] },
  { q: 'A key benefit of a stateless API server is:', opts: ['It keeps each user\'s session on the instance that created it', 'Any instance can serve any request, so instances are interchangeable', 'It removes the need for any shared session or token store', 'It guarantees a returning user reaches the same instance again'], a: 1, e: 'With no per-client state in the server process, a load balancer can send any request to any instance, so instances can be added, replaced, or lost mid-session. The state does not vanish, though: it moves into a signed token or a shared store such as Redis or the database, and that store is now on the critical path.', intro: 'If the next request lands on a different instance, what must the server not be holding on to?', tags: ['System Design', 'stateless'] },
  { q: 'A mobile screen needs a user, their latest orders, and only three fields from each order. Which GraphQL property may reduce over-fetching compared with several fixed REST representations?', opts: ['Every resource is addressed through a separate fixed URL', 'The client selects the fields and related data it needs in one query', 'The API maps each query directly to one database table', 'Every response uses the same schema-free document shape'], a: 1, e: 'GraphQL clients select fields through a typed schema and can traverse related data in one operation. That flexibility also creates server-side complexity around authorization, caching, and query cost.', intro: 'Count what a fixed representation would send back here that the screen never displays.', tags: ['System Design', 'graphql'] },
  { q: 'gRPC is often chosen for:', opts: ['Public browser-facing APIs that need cacheable URLs', 'Service-to-service calls that need compact typed messages', 'Streaming large media files straight from object storage', 'Loosely typed webhooks delivered to third-party servers'], a: 1, e: 'gRPC sends Protocol Buffers over HTTP/2 by default, so internal calls stay compact and the schema generates matching client and server types. The cost is that payloads are not human-readable, every field change goes through code generation, and browsers need a gRPC-Web proxy - which is why public, cacheable APIs usually stay on JSON over HTTP.', intro: 'Weigh a binary, schema-compiled wire format: who gains from it, and who cannot read one easily?', tags: ['System Design', 'grpc'] },
  { q: 'Several backend services need one public entry point with shared authentication, quotas, and path routing. Which component fits?', opts: ['A service registry used only by internal clients', 'An API gateway in front of the backend services', 'A database proxy that routes SQL by table name', 'A CDN configured only for immutable static files'], a: 1, e: 'An API gateway can centralize edge concerns such as authentication, routing, rate limits, and response aggregation. Business rules should still live in the owning services.', intro: 'Sort the listed concerns into ones each service must own and ones that are identical for all of them.', tags: ['System Design', 'gateway'] },
  { q: 'A client times out and retries the same payment request. What does it mean if that endpoint is idempotent?', opts: ['The retry is rejected with an error because it is a duplicate', 'The retried request leaves the same end state as a single request', 'The retry returns a byte-identical response to the first attempt', 'The retry is guaranteed to succeed because the endpoint cannot fail'], a: 1, e: 'RFC 9110 defines an idempotent method as one where the intended effect on the server of several identical requests is the same as for a single request, which is exactly what makes an automatic retry safe. The response may still differ - a repeated DELETE can answer 404 - and the call can still fail, so only the end state is constrained, not the reply or the outcome.', intro: 'The client cannot tell whether the first attempt was processed; ask what guarantee would make sending it again safe.', tags: ['System Design', 'idempotency'] },
  { q: 'Versioning an API (e.g. /v1/) helps by:', opts: ['It upgrades old clients to the new response shape automatically', 'It lets the response shape change while old clients keep working', 'It removes the need to plan for breaking changes at all', 'It makes each response faster because fewer fields are sent'], a: 1, e: 'A version in the path lets a breaking change ship under /v2/ while clients written against /v1/ keep receiving the old shape. The cost is real: both versions have to be served, tested, and eventually retired, so versioning buys time to migrate rather than removing the need to manage breaking changes.', intro: 'Think about a client shipped last year that nobody is going to redeploy.', tags: ['System Design', 'versioning'] },

  // Level 3 — Scaling: Vertical vs Horizontal
  { q: 'Vertical scaling ("scaling up") means:', opts: ['Adding more machines behind a load balancer', 'Adding CPU, memory, or faster disks to one machine', 'Moving the same workload to a managed service', 'Splitting the data set across several database nodes'], a: 1, e: 'Vertical scaling makes a single machine bigger - more CPU, more memory, faster storage - and usually needs no application change, which is why it is the cheapest first move. It is bounded by the largest machine available, the price per unit of capacity climbs at the top of the range, and that machine remains a single point of failure.', intro: 'Decide whether the extra capacity arrives inside one machine or as more machines.', tags: ['Scaling', 'vertical'] },
  { q: 'Horizontal scaling ("scaling out") means:', opts: ['Replacing the server with a larger machine', 'Adding more instances that share the incoming load', 'Reducing the work each individual request performs', 'Moving background jobs to off-peak hours'], a: 1, e: 'Horizontal scaling adds instances and spreads requests across them, so capacity is no longer capped by one machine and losing one instance is survivable. The price is coordination: instances must be stateless or share state through an external store, and a load balancer plus deployment and health tooling becomes part of the design.', intro: 'Scaling adds capacity rather than trimming demand; then ask where the extra capacity comes from.', tags: ['Scaling', 'horizontal'] },
  { q: 'A major limitation of vertical scaling is:', opts: ['It cannot be applied without changing application code', 'It hits a hardware ceiling and stays one point of failure', 'It requires the workload to be split across many nodes', 'It costs steadily less per unit of capacity as the machine grows'], a: 1, e: 'A machine can only be made so large, and near the top of the range the price per unit of capacity climbs sharply rather than falling. The harder limit is that the whole service still sits on that one machine, so a failure or a reboot is an outage - which is why growth past that point usually means scaling out.', intro: 'Check each claim against one very large server: which is still true when the machine is as big as money can buy?', tags: ['Scaling', 'vertical'] },
  { q: 'Horizontal scaling generally requires application servers to be:', opts: ['Stateful', 'Stateless (or sharing state via an external store)', 'Single-threaded', 'Written in one language'], a: 1, e: 'To freely add instances behind a load balancer, servers should keep no local per-client state (use Redis/DB for shared state).', tags: ['Scaling', 'stateless'] },
  { q: 'Traffic follows unpredictable daily spikes. Which auto-scaling policy responds to actual demand?', opts: ['Add instances on a fixed midnight schedule in every region', 'Add or remove instances from request rate or CPU signals', 'Keep one large instance and restart it when its queue grows', 'Raise the instance size once and leave the count fixed'], a: 1, e: 'Metric-based auto-scaling changes the instance count in response to observed demand, which is the only one of these that tracks an unpredictable curve. A fixed schedule or a one-off larger instance sets capacity in advance, and thresholds plus cooldowns are what keep the metric-driven policy from oscillating.', intro: 'The traffic is unpredictable, so the policy has to read something that moves with it.', tags: ['Scaling', 'autoscale'] },
  { q: 'Why is statefulness on app servers a problem for scaling?', opts: ['It forces every request to read from the database first', 'A session tied to one instance breaks when routing changes', 'It prevents the application from using an external cache', 'It makes deployments slower but does not affect requests'], a: 1, e: 'Local session state means a user\'s later requests have to reach the same process, so a routing change, a deploy, or an instance dying logs them out or loses their work. Moving sessions into a shared store or a signed token lets any instance serve them, which is what allows the pool to grow, shrink, and be replaced freely.', intro: 'Follow one user\'s second request when the balancer sends it to a different instance.', tags: ['Scaling', 'state'] },
  { q: 'Sessions are stored in each app server’s memory. Which load-balancer setting can reduce random logouts without changing session storage?', opts: ['Route every request to the least busy server', 'Route the same user to the same server when possible', 'Send writes to one server and reads to another', 'Retry a failed request on the next server in rotation'], a: 1, e: 'Session affinity, or sticky sessions, pins a user to one instance so the in-memory session is still there on the next request. It is a stopgap: the session is still lost when that instance is redeployed or dies, and pinning skews load, so shared external session storage remains the better fix.', intro: 'Ask what the balancer would have to keep constant for a session held in one process to still be found.', tags: ['Scaling', 'sessions'] },
  { q: 'A practical scaling order is often:', opts: ['Shard first, always', 'Optimize/scale vertically and add caching/replicas before sharding', 'Rewrite in another language first', 'Add SPOFs'], a: 1, e: 'Sharding is complex; teams usually exhaust caching, read replicas, and vertical/horizontal app scaling first.', tags: ['Scaling', 'strategy'] },

  // Level 4 — Load Balancing
  { q: 'Four stateless API instances are healthy, but clients know only one public address. Which component should receive that traffic?', opts: ['A read replica that forwards writes to the primary', 'A load balancer that routes requests across the API instances', 'A message broker that turns every request into a background job', 'A CDN configured to cache every authenticated response'], a: 1, e: 'A load balancer gives clients one entry point and spreads requests across healthy application instances. The other components solve storage, asynchronous work, or caching problems.', intro: 'Which of these components makes a routing decision for every request it receives?', tags: ['Load Balancing', 'basics'] },
  { q: 'Three equal app servers handle requests of roughly equal cost. Which simple policy distributes successive requests A, B, C, A, B, C?', opts: ['Least connections', 'Round-robin', 'IP hash', 'Weighted failover'], a: 1, e: 'Round-robin cycles through servers in order. It works well when instances and request costs are similar; least-connections is often better when request duration varies.', intro: 'The rotation depends only on the order requests arrive, not on what each server is doing.', tags: ['Load Balancing', 'round-robin'] },
  { q: 'One app instance still accepts TCP connections but returns 500 for every request. What lets the load balancer remove it from rotation?', opts: ['An application-level health check that fails on that instance', 'A process restart policy with no load-balancer check', 'A round-robin policy that keeps sending occasional requests', 'TLS termination at the load balancer'], a: 0, e: 'An application-level health check detects that the instance cannot serve requests and removes it from rotation. A supervisor may restart it, but that does not replace routing health checks.', intro: 'An open TCP port only proves the process is listening; ask what would notice the 500s.', tags: ['Load Balancing', 'health'] },
  { q: 'API requests vary from 20 ms to 30 seconds. Which routing policy best accounts for servers tied up by long requests?', opts: ['Round-robin in fixed rotation', 'Least connections', 'IP hash on the client address', 'Random choice among healthy servers'], a: 1, e: 'Least-connections routing counts the requests still in flight on each server, so a server tied up by a 30-second job stops receiving new work until it drains. Round-robin and IP hash assign by position or client address, so they keep sending requests to a server that is already saturated, and a 20 ms request can end up queued behind a 30-second one.', intro: 'Requests here differ by three orders of magnitude, so ask which signal reflects work still in flight.', tags: ['Load Balancing', 'algorithms'] },
  { q: 'An L7 (application-layer) load balancer can route based on:', opts: ['Only the client IP address and destination port', 'HTTP details such as path, headers, or cookies', 'Only the TLS certificate the backend presents', 'The order in which backends joined the pool'], a: 1, e: 'A layer-7 balancer parses the HTTP request, so it can route by path, host, header, or cookie and terminate TLS on the way. That parsing is the cost: it has to decrypt and buffer the request, which uses more CPU and adds more latency than a layer-4 balancer that forwards TCP connections without reading them.', intro: 'Layer 7 is the application layer; ask what the balancer has to parse to see that far.', tags: ['Load Balancing', 'L7'] },
  { q: 'One of four app instances fails during a deploy. Why can the service stay available behind a load balancer?', opts: ['Health checks divert traffic while the healthy instances absorb it', 'The balancer restores the failed instance\'s memory from a backup', 'The balancer queues every request until that instance returns', 'Every request is replayed from the database until it recovers'], a: 0, e: 'Health-aware routing stops sending new requests to the failed instance, and the remaining redundant instances take that share of the traffic. The balancer does not repair application state or hold requests until recovery, and it needs its own redundancy - otherwise the entry point is simply a different single point of failure.', intro: 'The other three instances have not changed; ask what happens to the traffic aimed at the fourth.', tags: ['Load Balancing', 'availability'] },
  { q: 'To avoid the load balancer itself being a SPOF you:', opts: ['Increase the balancer\'s connection limit and timeouts', 'Run redundant balancers with failover on a shared address', 'Add more application instances behind the one balancer', 'Move health checks from the balancer into each instance'], a: 1, e: 'A second balancer in active-passive or active-active, with failover through DNS or a floating address, means losing one does not take the entry point down. Adding application instances does not help here because every request still funnels through the single balancer - redundancy has to sit at the layer that would actually fail.', intro: 'Ask which component every request still passes through after you have added more instances.', tags: ['Load Balancing', 'redundancy'] },
  { q: 'TLS termination at the load balancer means:', opts: ['The balancer rejects any request that is not already encrypted', 'The balancer decrypts HTTPS and forwards plain HTTP', 'The connection closes as soon as the handshake ends', 'Certificates are installed on every backend instead'], a: 1, e: 'Terminating TLS at the balancer means the encrypted connection ends there: it decrypts the request, can then route on path or header, and forwards HTTP to the backends. Certificates and crypto cost live in one place, but the hop behind the balancer is now plaintext, so it must be a trusted network segment or be re-encrypted.', intro: '\'Termination\' names where the encrypted connection ends, not whether encryption happened.', tags: ['Load Balancing', 'tls'] },

  // Level 5 — Caching
  { q: 'A product catalog is read thousands of times between updates. Which change most directly reduces repeated database work?', opts: ['Add an index to the catalog table for each read path', 'Cache catalog responses and invalidate them on change', 'Move catalog reads onto a background queue', 'Split the catalog table across two database nodes'], a: 1, e: 'Between updates the answer is identical every time, so it can be computed once and served from faster storage until a product changes, with invalidation bounding how stale it gets. An index makes each query cheaper but the database still answers every read, and moving reads to a queue delays the work rather than removing it.', intro: 'Nothing about the data changes between those reads; ask what that fact makes possible.', tags: ['Caching', 'basics'] },
  { q: 'The API checks Redis for product 42, finds a valid value, and returns it without querying Postgres. What happened?', opts: ['A cache hit', 'A cache miss followed by a fill', 'An expired-entry refresh', 'A write-through update'], a: 0, e: 'A cache hit means the requested value was already present and valid. A miss or expired entry would require reading the source of truth.', intro: 'Ask whether anything had to be fetched or written before the response went out.', tags: ['Caching', 'hit-miss'] },
  { q: 'A cached price has a TTL of 60 seconds and no explicit invalidation. What does that setting guarantee?', opts: ['The entry becomes ineligible after about 60 seconds and must be refreshed', 'The entry can be read at most 60 times', 'The source price cannot change during those 60 seconds', 'The cache writes the price back to the database every 60 seconds'], a: 0, e: 'TTL means time to live. It limits how long an entry remains valid, but it does not stop the source data changing before expiry.', intro: 'Ask what the cache may still serve at second 59, and what the database is free to do in the meantime.', tags: ['Caching', 'ttl'] },
  { q: 'A profile is updated in the database, but some users still see the old value from cache. Why is cache invalidation difficult?', opts: ['A cache entry becomes immutable after its first read', 'Every relevant cached copy must expire or be invalidated when the source changes', 'A cache may use a TTL only when the backing store is SQL', 'Invalidation always requires deleting the source record too'], a: 1, e: 'The system must identify and refresh or remove every cached representation affected by a change. Missed dependencies, concurrent updates, and distributed copies make that coordination error-prone.', intro: 'Some users see the new value and some the old; ask what differs between those two groups.', tags: ['Caching', 'invalidation'] },
  { q: 'Users on three continents download the same versioned JavaScript bundle. Where should that bundle be cached?', opts: ['In the origin application server\'s local memory', 'At edge locations near users on each continent', 'In a per-user session record on the origin', 'In the primary database beside the product rows'], a: 1, e: 'A CDN keeps a copy of shared content at points of presence close to users, so the request stops crossing a continent and origin traffic drops with it. Caching in origin memory or a per-user record still leaves the network distance in place, which is the dominant cost here, and the versioned filename is what makes a long edge lifetime safe.', intro: 'The bundle is byte-identical for everyone and the users are far away; ask which distance a cache can remove.', tags: ['Caching', 'cdn'] },
  { q: 'A "cache stampede" (thundering herd) happens when:', opts: ['A cache node fills up and starts evicting cold keys', 'A hot key expires and many requests recompute it at once', 'A key is written far more often than it is read', 'Two writers update the same key in the wrong order'], a: 1, e: 'When a hot entry expires, every concurrent request misses and recomputes the same value, and that burst can overwhelm the backend the cache was protecting. Eviction, write-heavy keys, and lost updates are real cache problems too, but none of them produces the synchronized flood; a request lock, early recomputation, or jittered TTLs prevent it.', intro: 'Ask which of these problems hits many requests at the same instant rather than one request at a time.', tags: ['Caching', 'stampede'] },
  { q: 'Write-through caching means:', opts: ['Writes skip the cache and go only to the datastore', 'Writes update the cache and the datastore together', 'Writes go to the cache and are flushed to the datastore later', 'Writes invalidate the cached entry and then return'], a: 1, e: 'Write-through updates the cache and the datastore in the same operation, so a later read cannot find a stale entry - paid for with extra latency on every write. Write-around skips the cache and leaves the next read to miss, write-back defers the datastore write and can lose it on a crash, and invalidate-on-write avoids staleness by throwing the cached value away.', intro: 'The name says what the write passes through; ask what it has to touch before it returns.', tags: ['Caching', 'write-through'] },
  { q: 'Caching is most beneficial when data is:', opts: ['Written constantly and read rarely', 'Read far more often than it changes', 'Unique to every single request', 'Required to be exactly current on read'], a: 1, e: 'Caching pays when the same value is served many times before it changes, because every hit avoids the work and the staleness window stays short. Data that is unique to each request is never read twice, and write-heavy data is invalidated again before it is reused. Data that must be exactly current can still be cached only if every write updates the cache in the same operation, which moves the cost onto the writes.', intro: 'A cached copy only pays off if it is reused; ask what has to be true between two reads.', tags: ['Caching', 'tradeoffs'] },

  // Level 6 — Databases at Scale (Replication)
  { q: 'A team keeps the same database records on nodes in two availability zones. Which technique is this?', opts: ['Archiving old rows to cold storage', 'Replication across database nodes', 'Vertical partitioning by column', 'Hash sharding by customer id'], a: 1, e: 'Replication keeps copies of the same records on more than one node, which is what makes failover and read scaling possible. Sharding and vertical partitioning divide the data instead, so no single node holds the whole set. The price of replication is the lag between copies and the storage each extra copy consumes.', intro: 'The same records exist in two places; ask whether the data was copied or divided.', tags: ['Replication', 'basics'] },
  { q: 'A primary-replica database receives an order update and later serves catalog reads. Which routing is typical?', opts: ['Send every write to any replica and merge conflicts later', 'Send the write to the primary and allow suitable reads from replicas', 'Send writes only to replicas and reads only to the primary', 'Send the write to the primary, then read it back from a replica to confirm it'], a: 1, e: 'Writes go to the primary, which ships the change to its replicas, and reads that tolerate a slightly older copy are routed to them; a PostgreSQL standby, for example, continuously applies WAL from the primary and answers read-only queries. A replica cannot accept an independent write, and reading a write back from a replica can miss it while that replica is still catching up.', intro: 'Decide which node has to see a change first, and what the copies are useful for once it has.', tags: ['Replication', 'primary-replica'] },
  { q: 'A database is overloaded by product-page reads, while all writes already fit on the primary. What do read replicas improve?', opts: ['Write throughput by accepting independent updates', 'Read throughput by serving copies of the data', 'Transaction isolation on the primary', 'The amount of data one primary disk can store'], a: 1, e: 'Read replicas offload read queries. They do not normally accept independent writes, so they do not solve a write-throughput bottleneck.', intro: 'A copy can answer questions but cannot accept changes on its own; match that to the bottleneck described.', tags: ['Replication', 'reads'] },
  { q: '"Replication lag" can cause:', opts: ['Writes on the primary committing faster than they should', 'A replica returning slightly stale data just after a write', 'Reads on the primary returning older values than replicas', 'The primary losing committed data while it stays healthy'], a: 1, e: 'With asynchronous replication a replica applies a change after the primary has committed it, so a read routed to a replica immediately after a write can still return the previous value. The primary is never the stale one, and it does not lose committed data while it is healthy - that loss window appears only if you fail over to a replica that has not caught up.', intro: 'Asynchronous copying means one node applies a change after the other; ask what a read inside that gap sees.', tags: ['Replication', 'lag'] },
  { q: 'The primary database becomes unreachable, but a current replica is healthy. Which action restores write availability?', opts: ['Promote the replica to become the new primary', 'Spread read queries evenly across the remaining replicas', 'Restore last night’s backup over every healthy node', 'Keep accepting writes locally on each app server'], a: 0, e: 'Failover promotes a suitable replica to primary and redirects writers. Read balancing and backups are related operations, but they do not by themselves restore a writable leader.', intro: 'Ask which role the unreachable node held that none of the survivors currently has.', tags: ['Replication', 'failover'] },
  { q: 'A write is acknowledged only after a replica confirms it. What trade-off does this synchronous policy make?', opts: ['Lower write latency but a larger window for data loss', 'Higher write latency for stronger durability', 'Higher read throughput with no effect on writes', 'Lower storage use because only one copy is retained'], a: 1, e: 'Waiting for a replica to confirm adds a network round trip to every commit, so writes get slower. What that buys is durability: an acknowledged write already exists on a second machine. Asynchronous replication makes the opposite trade, returning sooner and losing anything not yet shipped if the primary fails.', intro: 'The acknowledgment now waits for a second machine; ask what that buys and what it costs.', tags: ['Replication', 'sync'] },
  { q: 'Multi-primary (multi-leader) replication adds the challenge of:', opts: ['Reads must always be served by the nearest node', 'Concurrent writes to one row that must be reconciled', 'Only one node may accept writes at any moment', 'Replicas can no longer be added without downtime'], a: 1, e: 'When more than one node accepts writes, two users can update the same row concurrently and both writes are locally valid, so the system needs a resolution rule - last-write-wins, a per-field merge, or a conflict-free data type - and each of those quietly discards or reshapes somebody\'s update. That is the price of local write latency and of surviving the loss of one leader.', intro: 'Ask what the topology stops preventing once more than one node may accept a write.', tags: ['Replication', 'multi-leader'] },
  { q: 'To read your own just-written data despite replica lag, you can:', opts: ['Read from any replica but retry the read once', 'Send that user\'s reads to the primary for a short window', 'Add more replicas so one of them is always current', 'Cache the write locally and serve every user from it'], a: 1, e: 'Read-your-writes sends the reads of the user who just wrote to the primary, or to a replica known to have caught up, for a short window after the write. Retrying does not make a replica current and adding replicas does not shorten lag; the cost of this fix is extra load on the primary, which is why it is scoped to that one user instead of everyone.', intro: 'Ask which reads actually need the newest value, and how few of them that is.', tags: ['Replication', 'consistency'] },

  // Level 7 — Sharding & Partitioning
  { q: 'One database can no longer hold every customer row. The team routes each customer id to one of several database nodes. Which technique is this?', opts: ['Vertical partitioning by column', 'Horizontal sharding by customer id', 'Primary–replica read scaling', 'Table indexing on customer id'], a: 1, e: 'Horizontal sharding distributes different rows across nodes using a shard key. Replication would copy the same rows instead.', intro: 'Each customer\'s rows land on exactly one node; ask whether that copies the data or divides it.', tags: ['Sharding', 'basics'] },
  { q: 'A good shard key:', opts: ['Uses the smallest column so routing stays cheap', 'Spreads data and load evenly and has high cardinality', 'Follows insertion time so new rows stay together', 'Changes as a record moves through its lifecycle'], a: 1, e: 'A shard key needs enough distinct values to fill every shard and a distribution that matches real traffic, or one shard ends up carrying most of the load. It also has to be stable, since changing a record\'s key means physically moving the row, and it should appear in the common query so most reads touch a single shard.', intro: 'Run each option forward: where do the rows land, and what happens on the day a record\'s key value changes?', tags: ['Sharding', 'shard-key'] },
  { q: 'Orders are sharded by country, and 70% of orders come from one country. What problem is most likely?', opts: ['The shard for that country receives a disproportionate share of data and traffic', 'Every query must contact all shards, including lookups by country', 'Replication lag makes the country value change between reads', 'The primary key can no longer be indexed inside any shard'], a: 0, e: 'A skewed shard key creates a hotspot: one shard carries much more load than the others. Shard-key choice should distribute the expected traffic, not just the schema values.', intro: 'Follow the 70%: how many of the shards do those orders actually reach?', tags: ['Sharding', 'hotspot'] },
  { q: 'Cross-shard queries (e.g. JOINs across shards) are:', opts: ['Handled by the shard router at no extra cost', 'Costly: they fan out to every shard and merge results', 'Rewritten automatically into single-shard queries', 'Only possible when both tables share a shard key'], a: 1, e: 'A query not confined to one shard is sent to every shard and its partial results merged above the database, so latency follows the slowest shard and joins, aggregates, and ordering have to be redone by the router or the application. Sharding buys write and storage capacity by giving up single-node query flexibility, which is why the shard key is picked so the common queries stay on one shard.', intro: 'The rows one query needs now sit on different machines; ask who assembles the answer.', tags: ['Sharding', 'queries'] },
  { q: 'A cache cluster adds one node. Which partitioning approach is designed to avoid remapping nearly every key?', opts: ['Hash the key and take it modulo the node count', 'Consistent hashing over a ring of nodes', 'Sort every cached value and assign equal row counts', 'Add a secondary index that points to the new node'], a: 1, e: 'Consistent hashing places nodes and keys on a ring, so adding a node reassigns only the range that falls next to it. Taking the hash modulo the node count instead changes almost every key\'s destination: moving from four nodes to five relocates 80% of keys, which for a cache means nearly every entry misses at once.', intro: 'Ask what happens to every key\'s destination when the node count goes from N to N+1.', tags: ['Sharding', 'consistent-hashing'] },
  { q: 'A profiles table moves its large biography and avatar metadata into a separate table keyed by user id. Which technique is this?', opts: ['Horizontal partitioning by user-id ranges', 'Vertical partitioning by groups of columns', 'Time partitioning by creation month', 'Hash sharding across database nodes'], a: 1, e: 'Vertical partitioning separates columns that have different access patterns. Horizontal partitioning and sharding split rows instead.', intro: 'Every user still has exactly one profile; ask whether rows or columns were moved.', tags: ['Sharding', 'vertical-partition'] },
  { q: 'Range-based sharding (e.g. by date) risks:', opts: ['Ranges that can never be split once created', 'The newest range taking most writes while old ones idle', 'Losing the ability to query by a date range', 'Every query having to visit all of the ranges'], a: 1, e: 'Sharding by date sends every new row into the newest range, so one shard absorbs almost all writes while the older shards sit idle - the load follows time rather than data size. Hashing the key spreads writes evenly but gives up the cheap ordered scan that made range sharding attractive in the first place, and that is the actual choice being made.', intro: 'Ask which range a row inserted today belongs to, and where tomorrow\'s rows go.', tags: ['Sharding', 'range'] },
  { q: 'A read-heavy app still fits on one database, and repeated catalog queries cause most of the load. What should the team try before sharding?', opts: ['Shard the catalog table across four database nodes now', 'Add targeted caching and, if needed, read replicas', 'Increase the connection pool size on the application servers', 'Add a second application server behind the load balancer'], a: 1, e: 'Repeated identical queries are exactly what a cache removes, and read replicas add read capacity without changing the data model, so both fit the bottleneck that was actually measured. Sharding earns its routing and query complexity only once writes or data size outgrow one node, and more application servers or a larger connection pool just send the same repeated queries to the same database.', intro: 'The data still fits on one node and the same queries repeat; ask what those two facts rule in.', tags: ['Sharding', 'strategy'] },

  // Level 8 — Message Queues & Async
  { q: 'Checkout should respond before receipt email and analytics finish. Which design separates those tasks from the request?', opts: ['Call both dependencies synchronously before returning', 'Publish jobs to a queue for independent workers', 'Run both tasks in the browser after payment', 'Wrap every dependency call in one database transaction'], a: 1, e: 'A queue lets checkout hand work to independent consumers and return promptly. The jobs can be retried and scaled without coupling their latency to the user request.', intro: 'The user is waiting on the response; ask which of this work has to finish before it is sent.', tags: ['Queues', 'basics'] },
  { q: 'Image processing takes seconds and traffic arrives in bursts. What benefit does putting jobs on a queue provide?', opts: ['Uploads are rejected during a burst so the backlog never grows', 'The queue absorbs the burst and workers drain it at a steady rate', 'Each job is delivered exactly once, so handlers need no deduplication', 'Processing finishes sooner because the queue runs jobs in parallel itself'], a: 1, e: 'A queue decouples arrival from processing: a burst becomes a backlog that drains at the rate the workers sustain, instead of timing out uploads at the peak. The queue adds no processing capacity of its own - that comes from running more workers - and most brokers deliver at least once, so handlers still have to tolerate a repeat.', intro: 'Compare the rate jobs arrive at the peak with the rate the workers can sustain; ask what the gap does.', tags: ['Queues', 'async'] },
  { q: 'In pub/sub, an order-placed event is published to a topic that has three subscriptions. Who receives it?', opts: ['One consumer, chosen from all subscribers of the topic', 'Each of the three subscriptions receives its own copy', 'Only the subscription that acknowledges it first', 'All three, but only after the publisher confirms delivery'], a: 1, e: 'In publish/subscribe the broker delivers the message to every subscription attached to the topic, so all three get their own copy and process it independently - that fan-out is what decouples the publisher from its consumers. A point-to-point queue works the other way, handing one message to one consumer. Within a single subscription or consumer group, several worker processes still share the messages, so the event is handled once per subscription rather than once per process.', intro: 'The publisher does not know who is listening; ask what that implies about the number of deliveries.', tags: ['Queues', 'pubsub'] },
  { q: 'A broker promises at-least-once delivery. A worker may finish a job and crash before acknowledging it. What property should the handler have?', opts: ['It should acknowledge each message before starting the work', 'It should be idempotent so a second delivery has no extra effect', 'It should keep a counter in process memory to spot repeats', 'It should process messages one at a time in arrival order'], a: 1, e: 'At-least-once delivery means a lost acknowledgment causes redelivery, so the handler can see the same message twice; an idempotency key, a dedup table, or a transactional write makes the second run harmless. Acknowledging before doing the work prevents the duplicate but turns a crash into a lost job, and in-process state does not survive the crash that caused the redelivery.', intro: 'The work finished but the acknowledgment never arrived; ask what the broker does next.', tags: ['Queues', 'delivery'] },
  { q: 'A dead-letter queue (DLQ) holds:', opts: ['Messages waiting for a consumer that has not started yet', 'Messages that exceeded the retry limit, kept for inspection', 'Messages that were processed successfully and acknowledged', 'A backup copy of every message the queue has ever accepted'], a: 1, e: 'A broker moves a message to the dead-letter queue once it has been received and failed more times than the configured limit (SQS calls this maxReceiveCount). The point is to unblock the source queue: without a DLQ a poison message is redelivered forever and starves the consumers behind it. It is not an archive of successful messages and not a backup, because nothing reaches it unless processing failed.', intro: 'Think about the one message a consumer can never process. Where should the broker put it so the rest of the queue keeps moving?', tags: ['Queues', 'dlq'] },
  { q: 'Backpressure is about:', opts: ['Adding more producers so the queue drains faster', 'Signaling producers to slow down when consumers fall behind', 'Buffering without limit so producers never have to wait', 'Discarding the oldest messages to keep the queue length fixed'], a: 1, e: 'Backpressure carries the consumer\'s limit back to the producer, so the producer blocks, slows, or is refused instead of piling work up. Unbounded buffering only moves the failure: memory or disk fills and the system fails later and harder. Dropping the oldest messages is load shedding, a different choice that trades data loss for a bounded queue.', intro: 'The queue is growing because one side is faster than the other. Which side has to hear about it?', tags: ['Queues', 'backpressure'] },
  { q: 'Order service publishes OrderPlaced without knowing which teams consume it. Billing and analytics subscribe independently. What property does this create?', opts: ['Tight runtime coupling because the producer calls every consumer', 'Loose coupling through an event contract, with eventual processing', 'Immediate consistency across every subscriber by default', 'One shared database schema that all services must write'], a: 1, e: 'The producer depends on the event contract rather than each consumer’s address or uptime. This reduces runtime coupling, while introducing delivery, ordering, and consistency concerns.', intro: 'Nobody in the order service knows Billing exists. Ask what the producer now depends on instead.', tags: ['Queues', 'event-driven'] },
  { q: 'A trade-off of asynchronous processing is:', opts: ['Reads become strongly consistent as soon as the producer returns', 'Eventual consistency plus ordering, retry, and monitoring work you now own', 'Exactly-once delivery, which the broker provides by default', 'Lower end-to-end latency for the work that was moved off the request'], a: 1, e: 'Async handoff returns control to the caller before the work is done, so other readers can see stale state until the consumer catches up, and retries, ordering and queue depth become yours to operate. End-to-end latency usually goes up rather than down; only the response gets faster. Exactly-once is not free either: brokers deliver at least once, so handlers have to be idempotent.', intro: 'Moving work off the request path does not delete it. The caller stops waiting; ask what changes for everyone else.', tags: ['Queues', 'tradeoffs'] },

  // Level 9 — Consistency & CAP
  { q: 'Two database nodes cannot communicate. The service must either reject some operations or risk returning conflicting values. Which trade-off is this?', opts: ['Cost versus performance during normal operation', 'Consistency versus availability during a network partition', 'Latency versus storage when filling a cache', 'Read throughput versus write throughput when adding an index'], a: 1, e: 'CAP frames the choice between consistency and availability while a network partition exists. Partition tolerance is the condition, not an optional feature to trade away once the nodes cannot communicate.', intro: 'The nodes cannot reach each other, and that is a fact, not a setting. Ask which promise you break while it lasts.', tags: ['CAP', 'theorem'] },
  { q: 'During a network partition, a CP system favors:', opts: ['Availability, by letting each side keep answering independently', 'Consistency, by refusing requests it cannot confirm against a quorum', 'Latency, by answering from whichever replica is closest', 'Durability, by writing every request to disk before answering'], a: 1, e: 'A CP system keeps one agreed value during the partition, so the side that cannot reach a quorum stops answering and clients get errors or timeouts instead of a possibly divergent value. That is a real cost, not a free win: some share of traffic fails for as long as the split lasts. Answering from the nearest replica regardless of quorum is exactly the availability choice a CP system declines to make.', intro: 'One side of the split cannot confirm it holds the newest value. Decide whether it answers anyway.', tags: ['CAP', 'cp'] },
  { q: 'An AP system during a partition favors:', opts: ['Consistency, by blocking writes until every replica agrees', 'Availability, by answering from local state and reconciling later', 'Durability, by refusing writes it cannot copy to a second site', 'Latency, by dropping the slowest replica out of the cluster'], a: 1, e: 'An AP system answers from whatever replica the client can reach, so reads may be stale and two sides can accept conflicting writes. The bill arrives after the partition heals: something has to merge those versions, and last-write-wins silently discards one of them while version vectors hand the conflict back to the application. Blocking until every replica agrees is the consistency guarantee AP trades away.', intro: 'Ask whether clients on both sides of the split still get answers, and what the two sides owe each other once it heals.', tags: ['CAP', 'ap'] },
  { q: 'Eventual consistency means:', opts: ['Replicas differ permanently unless an operator repairs them', 'With no new writes, all replicas converge on the same value', 'Every read returns the value of the most recent committed write', 'Writes are applied in the same order on every replica immediately'], a: 1, e: 'Eventual consistency promises convergence only in the quiet period: stop writing, wait, and every replica ends up holding the same value. It says nothing about how long that takes or what any individual read sees in the meantime, which is why session guarantees such as read-your-writes get layered on top. A promise that every read sees the latest committed write is strong consistency, a much more expensive guarantee.', intro: 'The word to pin down is \'eventually\'. Under what condition does the guarantee actually come due?', tags: ['Consistency', 'eventual'] },
  { q: 'Strong consistency guarantees:', opts: ['Reads never block, because any replica may answer', 'Every read reflects the most recently committed write', 'Replicas agree once writes stop arriving', 'Writes survive the loss of an entire region'], a: 1, e: 'Strong consistency orders every read after the writes that have already committed, so a client never sees a value the system has replaced. Paying for that takes coordination - a leader or a quorum round trip - which adds latency to every operation and leaves the minority side of a partition unable to answer. Convergence only after writes stop is the weaker eventual guarantee, and surviving a lost region is durability, a separate property.', intro: 'Two clients, one right after the other. Ask what the second is promised about the first one\'s write.', tags: ['Consistency', 'strong'] },
  { q: 'Why is partition tolerance essentially mandatory in distributed systems?', opts: ['Networks inside one datacenter are reliable enough to ignore', 'Real networks drop, delay, and reorder messages, so splits happen', 'Partitions only affect systems spread across several regions', 'Consensus protocols remove partitions rather than survive them'], a: 1, e: 'Links fail, switches reboot, and a long garbage-collection pause looks exactly like a dead peer, so any system whose nodes talk over a network will sometimes be split - inside a single rack as well as across regions. Because you cannot opt out of that, the only choice left is how the system behaves while the split lasts. Consensus protocols such as Raft do not prevent partitions; they define which side may keep making progress.', intro: 'A partition is not a decision you get to decline. Ask who actually controls whether the network stays up.', tags: ['CAP', 'partition'] },
  { q: 'A banking ledger most likely prioritizes:', opts: ['Availability, letting each region answer with its own copy of the balance', 'Strong consistency for the authoritative balance, at some latency cost', 'Eventual consistency, because balances converge within a few minutes', 'Cache-first reads, because most accounts change balance rarely'], a: 1, e: 'A ledger carries an invariant that has to hold on every write - the same money cannot be spent twice - so the authoritative balance is kept under strong consistency, typically a single-writer partition or a quorum, and pays a coordination round trip for it. Letting each region answer from its own copy permits a double spend that later reconciles into a real loss. The split worth remembering is that a balance shown in an app may lag by seconds, while the balance a transfer is checked against may not.', intro: 'Two transfers hit the same account at the same moment from different regions. Ask what a wrong answer costs here.', tags: ['Consistency', 'tradeoffs'] },
  { q: 'A social media "like" counter can often tolerate:', opts: ['Strong consistency, so two viewers never see different counts', 'Eventual consistency, since a briefly stale count harms nothing', 'A single global writer, so no increment can ever be lost', 'A synchronous write to every replica before the request returns'], a: 1, e: 'Nothing downstream depends on the exact count at a given instant, so replicas can take increments locally and converge, which is what makes sharded counters and per-region aggregation possible on a very hot write path. Insisting on strong consistency here buys nothing a user can perceive and adds a coordination round trip to the most frequent write in the product. The trade is workload-specific: the same relaxation applied to an account balance would be a defect.', intro: 'Ask what actually breaks for a user if the number is short by three for one second.', tags: ['Consistency', 'tradeoffs'] },

  // Level 10 — Rate Limiting & Throttling
  { q: 'One API key sends 20,000 requests in a minute and crowds out normal clients. Which control addresses that behavior most directly?', opts: ['Require TLS for requests from that key', 'Cap requests for the key within a time window', 'Cache every response regardless of method or user', 'Add replicas without identifying the noisy client'], a: 1, e: 'Rate limiting bounds traffic for an identity, address, or route within a window. More capacity may help overall load, but it does not enforce fair or safe use by one client.', intro: 'Work out what makes this traffic a problem: the raw volume, or the fact that all of it comes from one key.', tags: ['Rate Limiting', 'basics'] },
  { q: 'The token bucket algorithm allows:', opts: ['A fixed number of requests per window, with no carry-over', 'Bursts up to the bucket size while holding an average refill rate', 'A constant output rate, delaying anything that arrives faster', 'Unlimited requests as long as the client retries after failures'], a: 1, e: 'Tokens are added at a steady rate up to a maximum, and each request spends one, so a client that has been quiet can spend the whole accumulated bucket at once and then falls back to the refill rate. AWS API Gateway exposes exactly these two knobs: the throttling rate is the refill and the throttling burst is the bucket capacity. A fixed window has no carry-over, and a leaky bucket smooths output rather than allowing the burst - permitting that burst is the reason to pick a token bucket at all.', intro: 'Tokens pile up while a client is idle. Ask what that idle client can do the moment it wakes up.', tags: ['Rate Limiting', 'token-bucket'] },
  { q: 'Which HTTP status code typically signals "rate limit exceeded"?', opts: ['403', '429', '503', '504'], a: 1, e: '429 Too Many Requests is the status for a client that has sent too many requests in a given time, defined in RFC 6585 section 4, and it may carry a Retry-After header. 403 refuses the request outright rather than inviting a later attempt, 503 says the server itself is unavailable, and 504 says an upstream did not answer in time. The distinction is operational: 429 and 503 tell a caller that backing off and retrying is the right move, while 403 tells it to stop.', intro: 'The server is healthy and the credentials are valid; the client simply asked too often. Which class of code puts the fault on the caller?', tags: ['Rate Limiting', 'http'] },
  { q: 'A "Retry-After" response header tells the client:', opts: ['That the client must not repeat this request at all', 'When the client may retry, as seconds or an HTTP date', 'How many requests the client has left in the current window', 'How long the server took to produce this response'], a: 1, e: 'Retry-After carries either a non-negative number of seconds or an absolute HTTP date, and appears on 429, 503 and some redirect responses. It replaces the client\'s guesswork: without it a caller falls back to its own backoff and may keep probing a server that knows exactly when it will be ready. It is not a remaining-quota counter, which is what the RateLimit headers carry, and it says nothing about how long the response itself took.', intro: 'The header shows up on 429 and on 503. Both mean \'not now\' - ask what the client still needs to be told.', tags: ['Rate Limiting', 'retry'] },
  { q: 'A gateway can shed excess load by rejecting it immediately or by holding it in a queue. Compared with immediate rejection, queuing the excess:', opts: ['Removes the need for a limit, because nothing is ever refused', 'Adds latency and queue depth, hiding overload until requests time out', 'Guarantees every request is served however long the overload lasts', 'Reduces the total work the service has to perform during the overload'], a: 1, e: 'Queuing smooths a short spike, and that is its entire value: it moves work in time rather than removing it. The cost is latency and a growing queue, so a sustained overload turns into client timeouts and retries against work the server is still holding, which is why queues need a bounded depth and a shed-on-full rule. Rejecting immediately with 429 is cheaper and lets the client back off with a Retry-After. Check what a product actually does: AWS API Gateway calls its limiter throttling but rejects with 429 rather than queuing.', intro: 'The requests are still there, just waiting. Ask what the caller sees meanwhile, and what happens if the overload does not stop.', tags: ['Rate Limiting', 'throttling'] },
  { q: 'Exponential backoff on the client means:', opts: ['Retry at a fixed interval until the call finally succeeds', 'Double the wait after each failure, with random jitter added', 'Retry immediately, but from only one client at a time', 'Give up after the first failure and surface the error'], a: 1, e: 'Each retry waits roughly twice as long as the previous one, and jitter randomizes the actual delay so clients that failed together do not come back together. Fixed-interval retries keep constant load on a struggling dependency and stay synchronized, which is how a recovering service gets knocked over a second time. Backoff needs a ceiling and a maximum attempt count too, or a client can sit waiting on work the user has already abandoned.', intro: 'Ten thousand clients just failed at the same instant. Ask what their retry times should look like.', tags: ['Rate Limiting', 'backoff'] },
  { q: 'Twelve API instances must enforce a single limit of 100 requests per minute per API key. What does that require?', opts: ['A shared counter store the instances read and write on each request', 'A local counter of 100 on each instance, which allows 1,200 in total', 'A local counter of 8 on each instance, which is exact under any routing', 'No coordination, because the load balancer distributes keys evenly'], a: 0, e: 'Only shared state lets twelve instances agree on one total, so the usual design is an atomic increment in Redis or a similar store, keyed by client and window. That is not free: every request pays a round trip and the limiter becomes a dependency that must itself stay available, which is why some systems accept a per-instance budget of limit/N instead. That approximation is not exact - with 100 spread over 12 instances each gets 8, so a key that happens to concentrate on one instance is cut off at 8 while the global budget is untouched. Accurate global limits and low limiter latency are the two ends of this trade.', intro: 'A single key can land on any of the twelve instances. Ask what each instance knows about the other eleven.', tags: ['Rate Limiting', 'distributed'] },
  { q: 'Why would a login endpoint apply a strict per-account and per-source rate limit?', opts: ['To make sure each account can hold only one active session', 'To slow brute-force guessing and absorb abusive request bursts', 'To keep the session table from growing as users sign in', 'To ensure failed logins are written to the audit log in order'], a: 1, e: 'Rate limits bound how quickly an attacker can try credentials and blunt credential-stuffing runs that reuse leaked passwords across many accounts. Per-account limits stop one account being ground down; per-source limits stop one host spraying many accounts, and you need both because either alone leaves the other pattern open. They complement rather than replace strong authentication, breach-password checks and monitoring.', intro: 'The limit is applied twice, per account and per source. Ask what each of the two scopes stops on its own.', tags: ['Rate Limiting', 'security'] },

  // Level 11 — CDNs & Edge
  { q: 'Users far from the origin repeatedly download the same versioned images. What is the CDN’s main role?', opts: ['Copy relational transactions to a database near each user', 'Serve cached image bytes from edge locations near users', 'Compile the frontend separately for every request', 'Queue image requests until the origin has spare capacity'], a: 1, e: 'A CDN places cacheable content at distributed edge locations. This shortens network paths and reduces repeated work at the origin.', intro: 'The bytes are identical every time and the users are far away. Ask which part of the cost is distance.', tags: ['CDN', 'basics'] },
  { q: 'Which response is the poorest fit for CDN caching as it stands?', opts: ['A versioned JavaScript bundle served to every visitor', 'An account page rendered with the signed-in user\'s balance', 'A product image reachable at a stable public URL', 'A public API response that changes at most once an hour'], a: 1, e: 'A CDN pays off when one stored copy answers many requests, so the deciding question is how many viewers share the same body for the same URL. A per-user account page has an audience of one and must not be shared with anyone else, which is why it is served private and no-store. The other three have a stable URL and a shared body, and even the hourly API response is cacheable with a short TTL. Personalized responses can be edge-cached only by adding the user to the cache key, which is extra work rather than a free win.', intro: 'A cache entry only earns its place if more than one request can use it. Ask who else could receive this exact response.', tags: ['CDN', 'static'] },
  { q: 'The same 2 MB image is served from an edge 20 ms away instead of an origin 180 ms away. What improves most directly?', opts: ['Network latency because the request travels a shorter path', 'Payload size because the edge automatically compresses every format', 'Server-rendering time because image delivery executes the page renderer', 'Freshness because edge responses do not need cache rules'], a: 0, e: 'A closer edge reduces network round-trip time. It does not inherently shrink the object, speed server rendering, or remove the need for cache-control and invalidation.', intro: '180 ms and 20 ms are round-trip times, not transfer times. Ask what a round trip is actually made of.', tags: ['CDN', 'latency'] },
  { q: 'Cache busting via filename hashing (e.g. app.3f9a.js) lets you:', opts: ['Purge the CDN on every deploy without changing the URL', 'Set a long max-age and still ship updates, because the URL changes', 'Skip the Cache-Control header, because the hash implies freshness', 'Reuse one URL forever while the CDN revalidates on every request'], a: 1, e: 'The hash is derived from the file contents, so any change produces a different URL that no cache has seen, which is what makes Cache-Control: max-age=31536000, immutable safe on the asset itself. The HTML that references the asset keeps a stable URL and must be revalidated instead, or visitors keep loading the previous bundle names and never see the new files. Hashing does not replace cache headers; it is what makes an aggressive one safe.', intro: 'A browser keys its cache on the URL. Ask what has to change before it will treat a file as new.', tags: ['CDN', 'cache-busting'] },
  { q: 'Edge computing/functions run code:', opts: ['In one central region, close to the primary database', 'At edge locations near users, far from most backend data', 'In the user\'s browser, alongside the rest of the page', 'Inside the CDN cache entry, as part of the stored response'], a: 1, e: 'Edge functions run in the CDN\'s points of presence, so a decision that needs no backend data - a redirect, an A/B assignment, a token check - reaches the user in a few milliseconds instead of crossing an ocean. The catch is that your database usually did not move: an edge function that queries a single-region store pays the long trip anyway and adds a hop, so it can be slower than simply running in that region. Edge placement pays off in proportion to how little origin data the decision needs.', intro: 'Ask which machines a CDN actually operates, and whether the data the code needs sits on them too.', tags: ['CDN', 'edge'] },
  { q: 'Many CDN edge locations miss the same popular object at once and would all contact the origin. What does an origin shield change?', opts: ['It sends every edge miss directly to a different origin replica', 'It funnels misses through another cache tier so the origin sees fewer requests', 'It disables edge caching and serves the object only from the shield', 'It encrypts cached objects but leaves origin request volume unchanged'], a: 1, e: 'An origin shield is a shared cache layer between edge points of presence and the origin. Edge caching still runs in front of it: the shield sees only the misses, and it consolidates concurrent misses for the same object into as few as one origin fetch. The tier is not free - CloudFront charges separately for requests that pass through Origin Shield, and AWS itself calls it a poor fit for dynamic or rarely requested content, which would miss at both layers.', intro: 'Fifty edges miss the same object in the same second. Ask what the origin sees if nothing sits between them.', tags: ['CDN', 'origin'] },
  { q: 'A downside of aggressive CDN caching is:', opts: ['The origin receives more requests than it would without caching', 'Clients keep serving an old copy until the TTL expires or you purge', 'Every request has to be revalidated with the origin before it is served', 'Responses can no longer be compressed at the edge'], a: 1, e: 'A long max-age lets the edge, and usually the browser, answer from the stored copy without asking the origin again, so a bad deploy stays visible until the TTL runs out or a purge propagates. Purges are not instantaneous and browser caches cannot be purged at all, which is why hashed filenames are preferred to long TTLs on stable URLs. The trade is explicit: aggressive caching buys origin offload and latency, and the price is losing the ability to change your mind quickly.', intro: 'You just deployed a fix. Ask who is still holding the version from before it.', tags: ['CDN', 'staleness'] },
  { q: 'TLS is terminated at the CDN edge rather than at your origin. What follows from that?', opts: ['The origin no longer needs its own certificate or transport encryption', 'The edge sees plaintext, so the origin still needs its own protected link', 'Requests can no longer be inspected or filtered before reaching the origin', 'Client certificates become the only remaining way to authenticate callers'], a: 1, e: 'Terminating TLS at the edge is what lets a CDN cache, compress, route and run a web application firewall on a request, because it can read it - which also means the edge holds a certificate for your domain and handles plaintext. The edge-to-origin hop is a separate connection that needs its own TLS and an origin authentication check, or anyone who can reach the origin address simply bypasses the edge. The same property is what makes edge DDoS absorption work: abusive traffic is dropped before it reaches or bills you.', intro: 'Someone has to hold a private key to read the request. Ask who that is now, and what the remaining hop looks like.', tags: ['CDN', 'security'] },

  // Level 12 — Failure Modes & Resilience
  { q: 'A recommendation service is useful but not required for checkout. How should checkout behave if recommendations time out?', opts: ['Fail the entire checkout to keep every page section consistent', 'Omit recommendations and keep the purchase path working', 'Retry recommendations without a deadline before showing checkout', 'Return success but delay writing the order until recommendations recover'], a: 1, e: 'Designing for failure means containing dependency failures and preserving core behavior. Here, recommendations can degrade gracefully while checkout remains correct.', intro: 'One of these page sections takes the money. Ask whether the other one is allowed to stop it.', tags: ['Resilience', 'philosophy'] },
  { q: 'A payment dependency is timing out, and retries are exhausting every request thread. How can a circuit breaker help?', opts: ['Retry each call continuously with no delay until it succeeds', 'Fail calls fast after repeated failures, then probe for recovery', 'Raise the timeout so slow calls get a chance to complete', 'Queue the failing calls until the dependency answers again'], a: 1, e: 'Once the failure threshold is crossed the breaker opens and calls return immediately instead of holding a thread for the full timeout, which is what keeps the caller from being dragged down with its dependency. A half-open state then admits a few probes, so the breaker closes again on its own when the dependency recovers. Raising the timeout or queuing the calls makes thread exhaustion worse, because the caller holds more in-flight work for longer.', intro: 'Every one of those calls is going to fail anyway. Ask what the thread waiting on it is worth.', tags: ['Resilience', 'circuit-breaker'] },
  { q: 'Graceful degradation means:', opts: ['The whole system goes down on any error', 'Non-critical features fail/turn off while core functionality keeps working', 'Ignoring all errors', 'Doubling latency'], a: 1, e: 'Graceful degradation sheds non-essential features under stress so the core service stays available.', tags: ['Resilience', 'degradation'] },
  { q: 'A timeout on a downstream call prevents:', opts: ['The dependency from being overloaded by concurrent requests', 'Caller threads and connections from being held indefinitely', 'Errors from reaching the user, by falling back automatically', 'The request from being retried after a transient failure'], a: 1, e: 'A timeout bounds how long the caller waits, so the thread, socket and connection-pool slot are returned and the caller stays responsive while the dependency is sick. Without one, a slow dependency quietly consumes every worker and the outage climbs upstream. The cost is real in the other direction: too tight a timeout turns slow successes into failures and multiplies load through retries, so the value belongs just above the dependency\'s normal tail latency rather than at a round number.', intro: 'The dependency is slow rather than down, so nothing ever comes back. Ask what the caller is still holding.', tags: ['Resilience', 'timeouts'] },
  { q: 'Retries should be paired with backoff and jitter to avoid:', opts: ['Requests arriving out of the order the client sent them', 'Synchronized retry storms that hammer a recovering service', 'Duplicate side effects when one request is processed twice', 'Connection pools filling with sockets the server already closed'], a: 1, e: 'Clients that failed together retry together unless something separates them, so a service that recovers with partial capacity is knocked straight over by the whole backlog arriving at once. Exponential growth thins the traffic and jitter breaks the synchronization, and you need both: pure exponential backoff still lines every client up on the same schedule. Duplicate side effects are the other problem retries create, and the fix for that is idempotency keys rather than timing.', intro: 'The service just came back with a fraction of its capacity. Ask what every waiting client does at that instant.', tags: ['Resilience', 'retries'] },
  { q: 'A "cascading failure" is when:', opts: ['Several independent components fail at the same time by coincidence', 'One component\'s failure shifts load onto others until they fail too', 'A deploy is rolled back automatically after its health checks fail', 'A single request takes a slow path through every service in turn'], a: 1, e: 'What makes it a cascade is that the second failure is caused by the first: the load, retries and connections the dead component was absorbing land on the remaining ones and push them past their own limits. That is why the cure is containment - bulkheads, breakers, load shedding, capacity headroom - rather than only restarting the first component, which comes back into the full load and dies again. Independent components failing at the same moment is correlated bad luck, not a cascade.', intro: 'One node in the pool just died. Ask where its traffic goes and what that does to the survivors.', tags: ['Resilience', 'cascading'] },
  { q: 'The bulkhead pattern improves resilience by:', opts: ['Sharing one connection pool so every caller gets equal access', 'Splitting pools per dependency so one failure cannot drain the rest', 'Restarting a component automatically when its health check fails', 'Duplicating each component so a standby can take over instantly'], a: 1, e: 'Give each dependency its own pool of threads or connections and a hung dependency can exhaust only its own share, so calls to healthy dependencies keep being served. The cost is utilization: partitions cannot lend spare capacity to one another, so you provision for each partition\'s peak instead of the aggregate, and sizing one too small creates queuing that a single shared pool would not have had. Auto-restart and standby replicas address a different failure - a component that is gone rather than one that is slow.', intro: 'Every outbound call currently draws from the same pool. Ask what one hung dependency can take from the others.', tags: ['Resilience', 'bulkhead'] },
  { q: 'Chaos engineering involves:', opts: ['Deploying without a test suite to see what breaks in production', 'Injecting controlled failures to test whether the system behaves as designed', 'Reordering deploys at random so no release goes out the same way twice', 'Load testing a staging copy until it stops responding'], a: 1, e: 'A chaos experiment starts from a stated prediction about how the system should behave when a dependency dies or a zone disappears, then causes exactly that failure and checks the prediction, with a bounded blast radius and a way to stop. It surfaces resilience assumptions that were never true - an uncapped retry, a failover nobody had exercised - which testing against a healthy system cannot reveal. Load testing pushes a system to its capacity limit, a different question; and without the hypothesis and the abort switch this is not an experiment, just a self-inflicted outage.', intro: 'The point is not to break things. Ask what you are trying to find out before an outage finds it for you.', tags: ['Resilience', 'chaos'] },

  // Level 13 — Observability & Monitoring
  { q: 'The three common "pillars of observability" are:', opts: ['Dashboards, alerts, and runbooks', 'Logs, metrics, and traces', 'Logs, metrics, and dashboards', 'Uptime, latency, and error rate'], a: 1, e: 'Logs are discrete events, metrics are numbers aggregated over time, and traces record one request\'s path across services - three shapes of raw telemetry, each answering questions the others cannot. Dashboards, alerts and runbooks are built on top of those signals rather than being signals, and uptime, latency and error rate are three particular metrics, not three categories. Treat the pillars as a coverage checklist rather than a standard: the real test is whether you can answer a new question without shipping new code.', intro: 'Ask whether each list names kinds of telemetry, particular measurements, or tools built on top of telemetry.', tags: ['Observability', 'pillars'] },
  { q: 'Metrics are best described as:', opts: ['Discrete events recorded with their full context', 'Numeric series aggregated over time, such as request rate or latency', 'The timed path of one request across several services', 'Samples of stack state collected while the process runs'], a: 1, e: 'Metrics are pre-aggregated numbers on a time axis, which is what makes them cheap to retain for a long time and fast to query, so dashboards and alerts run on them. The cost is context: a metric tells you the error rate rose, never which request failed or why, and adding a high-cardinality label such as user ID to recover that context is exactly what makes a metrics bill explode. Logs keep per-event context and traces keep per-request paths; the three complement each other rather than substitute.', intro: 'You want to alert when the error rate crosses a threshold over five minutes. Ask which signal is already in that shape.', tags: ['Observability', 'metrics'] },
  { q: 'One checkout request crosses four services, but the team cannot tell where its extra two seconds were spent. Which signal is most useful?', opts: ['Encrypted log storage without shared request context', 'A distributed trace with spans for the request across services', 'One host-level CPU average for the whole cluster', 'A database shard count from the deployment configuration'], a: 1, e: 'Distributed tracing propagates trace context and records timed spans across service boundaries, revealing the end-to-end path, errors, and bottlenecks.', intro: 'Nobody knows which of the four hops is holding the two seconds. Ask what you would need to record to find out.', tags: ['Observability', 'tracing'] },
  { q: 'Structured logging means logs are:', opts: ['Free-form prose lines written for a human to read', 'Machine-parseable key/value records, usually JSON, that can be queried', 'Lines that always follow the same fixed column order', 'Lines forwarded to a central store rather than kept on the host'], a: 1, e: 'Structured logs carry named fields - user_id, request_id, duration_ms - so a query can filter and aggregate on them directly, and those same fields let you join a log line to a trace or a metric. A fixed column order is still text a parser has to guess at, and shipping prose to a central store does not make it queryable. The cost is discipline and volume: field names have to stay consistent across services, and JSON lines are bigger than the prose they replace.', intro: 'Ask what a query engine has to do with the line \'user 12 failed after 3 tries\' before it can count failures per user.', tags: ['Observability', 'logging'] },
  { q: 'A team commits that 99.9% of API requests will finish within 300 ms over 30 days. What is that target?', opts: ['An SLA that automatically defines customer compensation', 'An SLO: a target value for a measured reliability indicator', 'An SLI: the individual latency measurement from one request', 'An error budget: the total number of requests the service receives'], a: 1, e: 'A service-level objective (SLO) sets a target for a service-level indicator (SLI). The allowed shortfall from that target forms the error budget; an SLA is a separate external agreement.', intro: 'Separate the thing being measured from the target set for it. Which of the two is this sentence stating?', tags: ['Observability', 'slo'] },
  { q: 'The "four golden signals" of monitoring are latency, traffic, errors, and:', opts: ['Uptime', 'Saturation', 'Throughput', 'Cost per request'], a: 1, e: 'Saturation is how full the service is against its most constrained resource - queue depth, pool occupancy, memory headroom - and it is the signal that warns first, because systems usually degrade well before they reach 100% utilization. Throughput is not a fourth signal; it is traffic under a different name. Uptime and cost per request are worth tracking, but neither tells you how close the service is to its limit.', intro: 'The other three all describe requests. Ask what the fourth signal has to be about instead.', tags: ['Observability', 'golden-signals'] },
  { q: 'Good alerting should be:', opts: ['Raised whenever CPU on any host passes 80 percent', 'Tied to a user-visible symptom and actionable by whoever is paged', 'Raised on every error log line, so that nothing is missed', 'Routed to the whole engineering team, so that someone always responds'], a: 1, e: 'Alert on what users feel - error rate, latency, an SLO burning down - and make sure the page names something a human can act on immediately; everything else belongs on a dashboard. A CPU threshold fires when nothing is wrong and stays quiet when something is, and a page per error line produces enough noise that the real one gets ignored. The cost of symptom alerting is that a page tells you what broke and not why, so it has to be paired with dashboards and traces for diagnosis.', intro: 'It is 3 a.m. and the page just fired. Ask what the person you woke up is supposed to do about it.', tags: ['Observability', 'alerting'] },
  { q: 'Logs from several services contain the same request ID. What investigation does that enable?', opts: ['Decrypting sensitive fields written by those services', 'Finding log events associated with one request across service boundaries', 'Reducing storage by merging all events into one log line', 'Reconstructing precise span timing without any other telemetry'], a: 1, e: 'A propagated correlation ID connects log records for one request. It complements tracing but does not by itself provide a full span model or timing hierarchy.', intro: 'Each service wrote its lines independently. Ask what the shared value lets you assemble, and what it still cannot tell you.', tags: ['Observability', 'correlation'] },

  // Level 14 — Trade-offs & Estimation
  { q: 'Before choosing storage for uploaded video, why estimate uploads per day, average size, and retention?', opts: ['To produce an exact bill that makes later measurement unnecessary', 'To check the order of magnitude and see which designs are feasible', 'To prove that a distributed design is required before building anything', 'To replace load tests and production capacity monitoring'], a: 1, e: 'Back-of-the-envelope estimates expose orders of magnitude and likely constraints. They guide an initial design; they do not replace measurement or load testing.', intro: 'You are choosing between designs, not writing an invoice. Ask how precise that decision actually needs to be.', tags: ['Estimation', 'basics'] },
  { q: 'If a service handles 1,000 requests/second steadily, that is roughly how many per day?', opts: ['~86 million', '~1 million', '~1 billion', '~3,600'], a: 0, e: '86,400 seconds per day times 1,000 requests per second is 86.4 million, so about 86 million. The habit worth taking away is the rounding: treat a day as 100,000 seconds and 1,000 requests per second becomes \'roughly a hundred million a day\' without a calculator. The other options imply very different systems - about 12 requests per second for a million a day, about 11,600 for a billion, and one request every 24 seconds for 3,600.', intro: 'You need one constant: the number of seconds in a day. Round it to make the multiplication easy.', tags: ['Estimation', 'math'] },
  { q: 'Two designs both meet the features. One costs less but has higher tail latency; the other is faster but harder to operate. How should the team choose?', opts: ['Select the architecture with the most services because it is more advanced', 'Compare the trade-offs against measured requirements and team constraints', 'Select the cheaper design because cost always outranks reliability', 'Select the faster design because latency always outranks complexity'], a: 1, e: 'System design rarely has one context-free winner. The right choice follows explicit requirements, expected load, cost, operational skill, and acceptable failure modes.', intro: 'Both designs already meet the features, so the feature list will not settle it. Ask what else you would need to know.', tags: ['Estimation', 'tradeoffs'] },
  { q: 'Premature optimization in system design tends to:', opts: ['Always pay off', 'Add complexity for scale you may never reach', 'Reduce all latency', 'Be required by CAP'], a: 1, e: 'Designing for imaginary scale wastes effort and adds complexity; design for realistic, near-term needs with room to grow.', tags: ['Estimation', 'yagni'] },
  { q: 'A service measures 40,000 reads per second and 400 writes per second against a single primary database. What does that ratio most directly argue for?', opts: ['Sharding the writes across several primaries before touching read load', 'Read replicas or a cache in front of the primary, accepting staleness', 'Dropping indexes so the primary spends less time maintaining them', 'Moving reads onto a queue so they are served asynchronously'], a: 1, e: 'Reads outnumber writes a hundred to one here, and reads are the part you can duplicate: replicas and caches both serve copies without coordinating, which is why they are the standard first move on a read-heavy workload. Both pay in freshness - a replica lags the primary, a cache entry lives until it expires or is invalidated - so this only works where a slightly old answer is acceptable. Sharding addresses write throughput and dataset size, and at 400 writes per second neither is the constraint.', intro: 'One of those two numbers is a hundred times the other. Ask which side of the workload the primary is spending its time on.', tags: ['Estimation', 'capacity'] },
  { q: 'An API reports p50 latency of 50 ms and p99 latency of 2 seconds. What does that distribution suggest?', opts: ['Every request finishes somewhere between 50 ms and 2 seconds', 'Typical requests are fast, but roughly the slowest 1% take about 2 seconds or more', 'The arithmetic mean latency is exactly 2 seconds', 'Only one request in the period was slower than 50 ms'], a: 1, e: 'The median describes the typical request while p99 exposes the slow tail. A p99 of 2 seconds bounds 99 requests in 100, not all of them, so it says nothing about how slow the worst ones get and does not mean every request lands between 50 ms and 2 seconds. At scale, even 1% can affect many requests and deserves investigation.', intro: 'p99 is a cut point in a distribution, not an average of one. Ask which requests it describes.', tags: ['Estimation', 'percentiles'] },
  { q: 'About how much raw storage do 1 billion rows of roughly 1 KB each need, before indexes and replication?', opts: ['~1 TB', '~1 GB', '~1 MB', '~1 PB'], a: 0, e: '10^9 rows times about 10^3 bytes is 10^12 bytes, which is a terabyte. Treat that as a floor rather than an answer: indexes, per-row overhead and a replication factor of three routinely take the real footprint to several times the raw figure, and that multiplier is what decides whether the dataset still fits on one machine. A gigabyte is a thousand times too small and a petabyte a thousand times too large, and errors that size pick the wrong storage engine.', intro: 'Count zeros rather than multiplying digits: how many does a billion have, and how many more does a kilobyte add?', tags: ['Estimation', 'storage'] },
  { q: 'A small team expects modest launch traffic but might grow later. Which starting architecture is usually easiest to justify?', opts: ['Split every capability into an independently deployed service immediately', 'Use the simplest design that meets current requirements, then evolve from measured constraints', 'Shard every table before collecting traffic or query data', 'Add caches at every layer even when the backing store meets the latency target'], a: 1, e: 'Architectural complexity creates operational cost. Begin with a design that meets known needs and preserve sensible evolution paths rather than paying for hypothetical scale.', intro: 'You do not yet have the traffic data that would justify a bigger design. Ask what you can still change later.', tags: ['Estimation', 'simplicity'] },

  // Level 15 — Designing Real Systems
  { q: 'Most URL-shortener traffic resolves a short code and redirects immediately. Which data-access shape dominates?', opts: ['A multi-table analytical join over every click event', 'A read-heavy key-to-value lookup from short code to destination URL', 'A cross-account transaction that locks many rows for each redirect', 'A graph traversal that discovers a path between two users'], a: 1, e: 'Redirects are simple, high-volume lookups by short code. A cache in front of a durable key-value mapping is a natural fit, while click analytics can use a separate path.', intro: 'Follow one redirect from start to finish. Ask how many rows it touches, and how often that happens per link created.', tags: ['Design', 'url-shortener'] },
  { q: 'A feed service precomputes each user\'s timeline when an author posts. What breaks when an author has 40 million followers?', opts: ['The read path, because every timeline is rebuilt on each view', 'The write path, because one post fans out to 40 million timelines', 'The storage layer, because the post text is stored 40 million times', 'The follower graph, because it must be re-sorted after each post'], a: 1, e: 'Fan-out on write buys very cheap reads by paying once per follower at write time, so a post from a very large account turns into tens of millions of inserts and a long tail of timelines that update minutes late. Real feeds go hybrid for exactly this reason: fan out on write for ordinary accounts, fan out on read for the few enormous ones, and merge at view time. Timelines hold post references rather than copies, so the pressure lands on write throughput and queue depth rather than on raw storage.', intro: 'Count the work a single post causes under this design, then compare it with the work a single feed view causes.', tags: ['Design', 'newsfeed'] },
  { q: 'A chat system commonly relies on:', opts: ['Clients polling a REST endpoint every few seconds for new messages', 'Persistent connections plus a durable store the client syncs from', 'Peer-to-peer connections between clients, with no server storage', 'A shared database each client connects to directly from the device'], a: 1, e: 'A long-lived connection lets the server push a message the moment it arrives instead of waiting to be asked, and a durable store with a per-conversation cursor lets a client that was offline catch up on reconnect; you need both, because the socket alone loses everything sent while it was down. Polling is a real and simpler design, but it trades either freshness or a flood of empty requests. The cost of persistent connections is connection state: each socket is pinned to one server, so reaching a user whose socket lives elsewhere needs a routing or pub/sub layer.', intro: 'Ask what has to happen when a message is sent to a user whose phone is asleep.', tags: ['Design', 'chat'] },
  { q: 'For a rate-limited public API, a critical component is:', opts: ['A CSS framework', 'A shared rate limiter (e.g. Redis-backed) at the gateway', 'A graph database', 'A spreadsheet'], a: 1, e: 'Public APIs need centralized rate limiting (often at the gateway, backed by Redis) to protect capacity and prevent abuse.', tags: ['Design', 'api'] },
  { q: 'To serve images globally with low latency you would use:', opts: ['One large application server in the primary region', 'Object storage behind a CDN, with the app serving only URLs', 'Image bytes stored as blobs in the primary relational database', 'Images generated on the client from data the API returns'], a: 1, e: 'Object storage holds large immutable blobs cheaply and hands out stable URLs, and a CDN caches those bytes near users, so the application server issues links instead of streaming files and never becomes the bottleneck. Putting image bytes in the relational database shares its buffer pool, backups and connection budget with your transactional rows, which degrades the whole database rather than just image serving. The cost of the split is that deletion and access control now span two systems, so private images need signed, expiring URLs rather than a permission check in a query.', intro: 'Ask which component should sit in the path of a 2 MB download, and which should never be in it.', tags: ['Design', 'media'] },
  { q: 'Idempotency keys are important in a payments API to:', opts: ['Let the client cancel a charge after it has been authorized', 'Let the server recognize a retried request and not charge twice', 'Prove that the request really came from the named merchant', 'Guarantee the payment provider answers within a fixed time'], a: 1, e: 'A client that never sees a response cannot tell a lost request from a lost reply, so it retries; the idempotency key lets the server recognize the second attempt as the same operation and return the original outcome instead of charging again. That obliges the server to store the key alongside the result for at least the length of any retry window, and to reject a reused key that arrives with a different body. Authenticating the caller and bounding response time are separate problems, and neither of them stops a double charge.', intro: 'The request went out and then the connection dropped before any response came back. Ask what the client does next.', tags: ['Design', 'payments'] },
  { q: 'Uploading a photo also creates four thumbnails, and resizing can take seconds. Which request flow is most resilient?', opts: ['Resize every thumbnail before acknowledging the upload', 'Store the upload, enqueue resize jobs, and let workers create thumbnails', 'Ask the browser to create the only permanent thumbnails', 'Run image processing in a database transaction that stays open until completion'], a: 1, e: 'Durably enqueueing the slow work keeps the request short and lets workers retry or scale independently. The design must also make repeated jobs safe.', intro: 'The user is waiting on an upload, not on four thumbnails. Ask what has to be durable before you answer them.', tags: ['Design', 'jobs'] },
  { q: 'You receive a broad prompt to design a messaging service. What is the strongest opening sequence?', opts: ['Name a full technology stack before asking about users or traffic', 'Clarify the required behavior and scale, sketch a simple flow, then examine bottlenecks and trade-offs', 'Choose a distributed database first and adapt every requirement to it', 'Draw every possible component before defining the critical request path'], a: 1, e: 'Start by narrowing requirements and scale. A simple end-to-end flow gives you something concrete to test against bottlenecks, failure modes, and trade-offs.', intro: 'You have not been told how many users, how large a message, or how quickly it must arrive. Ask what you do about that first.', tags: ['Design', 'method'] },
];
